// global.js
export let Id = -1;
export let StepId = -1

export const incrementId = () => {
  Id += 1;
  console.log('new id ', Id);
  return Id;
};

export const incrementStepId = () => {
  StepId += 1;
  console.log('new stepId ', Id);
  return StepId;
};
